// Problem: Find the first duplicate in an array
// Step 1: Restate the problem
public Integer findFirstDuplicate(int[] numbers) {
    // Clarifying questions I'd ask:
    // - Can the array be empty or null? (Handle edge case)
    // - Are numbers in any specific range? (Affects data structure choice)
    // - Do we return the value or the index? (Confirm output format)

    if (numbers == null || numbers.length < 2) {
        return null; // Edge case: can't have duplicate with <2 elements
    }

    // Step 2: Work through example BEFORE coding
    // Input: [2, 5, 1, 2, 3] → Output: 2 (first value seen twice)
    // Edge: [1, 2, 3] → Output: null (no duplicates)

    var seen = new HashSet<Integer>();
    for (int num : numbers) {
        if (seen.contains(num)) {
            return num; // First duplicate found
        }
        seen.add(num);
    }
    return null;
}

// Problem: Validate and parse user registration data
// Decompose into 3 sub-tasks: validate, parse, persist

public record UserRegistration(String email, String username, int age) {}

public class RegistrationService {

    // Main task: orchestrate sub-tasks
    public boolean registerUser(String rawData) {
        var validatedData = validateInput(rawData); // Sub-task 1
        if (validatedData.isEmpty()) return false;

        var user = parseUser(validatedData.get()); // Sub-task 2
        return saveToDatabase(user); // Sub-task 3
    }

    // Sub-task 1: Input validation (solve independently)
    private Optional<String> validateInput(String data) {
        if (data == null || data.isBlank()) return Optional.empty();
        return data.contains("@") ? Optional.of(data) : Optional.empty();
    }

    // Sub-task 2: Parsing logic (solve independently)
    private UserRegistration parseUser(String data) {
        var parts = data.split(",");
        return new UserRegistration(parts[0], parts[1], Integer.parseInt(parts[2]));
    }

    // Sub-task 3: Persistence (solve independently)
    private boolean saveToDatabase(UserRegistration user) {
        // Each function has one clear responsibility
        return user.age() >= 18; // Simplified validation
    }
}

// Problem: Find two numbers in an array that sum to a target

// STEP 1: Brute force - O(n²) time, O(1) space
public int[] findTwoSumBruteForce(int[] nums, int target) {
    // Try every pair - I know this is slow but it's correct
    for (int i = 0; i < nums.length; i++) {
        for (int j = i + 1; j < nums.length; j++) {
            if (nums[i] + nums[j] == target) {
                return new int[]{i, j};
            }
        }
    }
    return new int[]{};
}

// STEP 2: Optimized - O(n) time, O(n) space
public int[] findTwoSumOptimized(int[] nums, int target) {
    // Use HashMap to trade space for time
    var seen = new HashMap<Integer, Integer>(); // value -> index

    for (int i = 0; i < nums.length; i++) {
        int complement = target - nums[i];
        if (seen.containsKey(complement)) { // O(1) lookup vs O(n) inner loop
            return new int[]{seen.get(complement), i};
        }
        seen.put(nums[i], i);
    }
    return new int[]{};
}

// Problem: Track the most recent N user actions

// BAD: Using a List (insertion at front is O(n))
public class ActionTrackerSlow {
    private final List<String> actions = new ArrayList<>();
    private final int maxSize;

    public void addAction(String action) {
        actions.add(0, action); // O(n) - shifts all elements
        if (actions.size() > maxSize) {
            actions.remove(actions.size() - 1);
        }
    }
}

// GOOD: Using a Deque (insertion at front is O(1))
public class ActionTrackerFast {
    private final Deque<String> actions = new ArrayDeque<>();
    private final int maxSize;

    public ActionTrackerFast(int maxSize) {
        this.maxSize = maxSize;
    }

    public void addAction(String action) {
        actions.addFirst(action); // O(1) - optimized for this operation
        if (actions.size() > maxSize) {
            actions.removeLast(); // O(1) - remove from tail
        }
    }

    public List<String> getRecent() {
        return List.copyOf(actions); // Return immutable snapshot
    }
}

// Problem: Find all pairs with a given sum in an array

public List<int[]> findPairsWithSum(int[] nums, int target) {
    // Time complexity analysis:
    var result = new ArrayList<int[]>();        // O(1) - initialization
    var seen = new HashSet<Integer>();          // O(1) - initialization

    // This loop runs n times where n = nums.length
    for (int num : nums) {                      // O(n) - iterate array
        int complement = target - num;          // O(1) - arithmetic

        if (seen.contains(complement)) {        // O(1) - HashSet lookup
            result.add(new int[]{complement, num}); // O(1) amortized
        }
        seen.add(num);                          // O(1) - HashSet insertion
    }

    // Overall time: O(n) - single loop with O(1) operations inside
    // Space complexity: O(n) for 'seen' HashSet + O(k) for result where k = pairs found
    // Worst case space: O(n) if all elements form pairs

    return result;
}

